import{_ as o,r as s,o as p,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Модели - October CMS - 3.x","titleTemplate":false,"description":"Доступные модели, предоставляемые Tailor.","frontmatter":{"subtitle":"Доступные модели, предоставляемые Tailor."},"headers":[{"level":2,"title":"Запись Entry","slug":"запись-entry","link":"#запись-entry","children":[{"level":3,"title":"Доступные атрибуты","slug":"доступные-атрибуты","link":"#доступные-атрибуты","children":[{"level":4,"title":"Структурные записи","slug":"структурные-записи","link":"#структурные-записи","children":[]},{"level":4,"title":"Потоковые записи","slug":"потоковые-записи","link":"#потоковые-записи","children":[]}]},{"level":3,"title":"Получение нескольких записей","slug":"получение-нескольких-записеи","link":"#получение-нескольких-записеи","children":[]},{"level":3,"title":"Получение одной записи","slug":"получение-однои-записи","link":"#получение-однои-записи","children":[]},{"level":3,"title":"Вставка и обновление записей","slug":"вставка-и-обновление-записеи","link":"#вставка-и-обновление-записеи","children":[]}]},{"level":2,"title":"Глобальная запись","slug":"глобальная-запись","link":"#глобальная-запись","children":[{"level":3,"title":"Доступные атрибуты","slug":"доступные-атрибуты-1","link":"#доступные-атрибуты-1","children":[]},{"level":3,"title":"Получение глобальной записи","slug":"получение-глобальнои-записи","link":"#получение-глобальнои-записи","children":[]}]},{"level":2,"title":"Работа со связанными полями","slug":"работа-со-связанными-полями","link":"#работа-со-связанными-полями","children":[{"level":3,"title":"Жадная загрузка связей","slug":"жадная-загрузка-связеи","link":"#жадная-загрузка-связеи","children":[]},{"level":3,"title":"Создание связанных полей","slug":"создание-связанных-полеи","link":"#создание-связанных-полеи","children":[]}]},{"level":2,"title":"Расширение конструкторов моделей","slug":"расширение-конструкторов-моделеи","link":"#расширение-конструкторов-моделеи","children":[]},{"level":2,"title":"Расширение моделей Tailor","slug":"расширение-моделеи-tailor","link":"#расширение-моделеи-tailor","children":[{"level":3,"title":"Связывание Tailor с обычными моделями","slug":"связывание-tailor-с-обычными-моделями","link":"#связывание-tailor-с-обычными-моделями","children":[]},{"level":3,"title":"Связывание обычных моделей с Tailor","slug":"связывание-обычных-моделеи-с-tailor","link":"#связывание-обычных-моделеи-с-tailor","children":[]},{"level":3,"title":"Создание пользовательского поля контента","slug":"создание-пользовательского-поля-контента","link":"#создание-пользовательского-поля-контента","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/tailor/models.md","filePath":"3.x/ru/cms/tailor/models.md"}'),i={name:"3.x/ru/cms/tailor/models.md"};function d(u,n,k,g,h,f){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Модели",-1)),a(e),n[1]||(n[1]=r(`<p>В этой статье описывается взаимодействие с Tailor с помощью PHP и доступные модели.</p><h2 id="запись-entry"><a href="#запись-entry" class="header-anchor">#</a> Запись Entry</h2><p>Модель <code>Tailor\\Models\\EntryRecord</code> используется для хранения контента записи.</p><h3 id="доступные-атрибуты"><a href="#доступные-атрибуты" class="header-anchor">#</a> Доступные атрибуты</h3><p>В дополнение к определённым полям формы, в полученной модели доступны следующие атрибуты.</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>Первичный ключ в базе данных.</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>UUID связанного чертежа.</td></tr><tr><td><strong>content_group</strong></td><td>Имя группы контента, если используется.</td></tr><tr><td><strong>title</strong></td><td>Заголовок записи, например, <strong>My Blog Post</strong>.</td></tr><tr><td><strong>slug</strong></td><td>Идентификатор slug для записи, например, <code>my-blog-post</code>.</td></tr><tr><td><strong>is_enabled</strong></td><td>Определяет, видна ли запись в данный момент.</td></tr><tr><td><strong>created_at</strong></td><td>Дата создания записи.</td></tr><tr><td><strong>updated_at</strong></td><td>Дата последнего обновления записи.</td></tr><tr><td><strong>expired_at</strong></td><td>Дата истечения срока действия записи.</td></tr><tr><td><strong>published_at</strong></td><td>Дата публикации записи.</td></tr><tr><td><strong>published_at_date</strong></td><td>Дата публикации или, если не указана, дата создания.</td></tr></tbody></table></div><h4 id="структурные-записи"><a href="#структурные-записи" class="header-anchor">#</a> Структурные записи</h4><p>Если тип записи — <code>structure</code>, у неё будут дополнительные атрибуты.</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>fullslug</strong></td><td>Идентификатор slug, включающий slug родителей, например, <code>parent-slug/child-slug</code>.</td></tr><tr><td><strong>parent</strong></td><td>Родительская запись для этой записи, если доступна.</td></tr><tr><td><strong>children</strong></td><td>Дочерние записи для этой записи, если доступны.</td></tr></tbody></table></div><h4 id="потоковые-записи"><a href="#потоковые-записи" class="header-anchor">#</a> Потоковые записи</h4><p>Если тип записи — <code>stream</code>, у неё будут дополнительные атрибуты.</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>published_at_day</strong></td><td>Числовой день публикации записи.</td></tr><tr><td><strong>published_at_month</strong></td><td>Числовой месяц публикации записи.</td></tr><tr><td><strong>published_at_year</strong></td><td>Числовой год публикации записи.</td></tr></tbody></table></div><h3 id="получение-нескольких-записеи"><a href="#получение-нескольких-записеи" class="header-anchor">#</a> Получение нескольких записей</h3><p>Для работы с записью через PHP используйте модель <code>Tailor\\Models\\EntryRecord</code> и вызовите статический метод <code>inSection</code>, передав handle, чтобы получить подготовленный <a href="./../../extend/database/query.html">запрос к модели базы данных</a>. Альтернативно можно выполнить поиск по UUID с помощью метода <code>inSectionUuid</code>.</p><p>Следующий метод <code>get</code> возвращает <a href="./../../extend/services/collection.html">коллекцию записей</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;a63fabaf-7c0b-4c74-b36f-7abf1a3ad1c1&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="получение-однои-записи"><a href="#получение-однои-записи" class="header-anchor">#</a> Получение одной записи</h3><p>В сочетании с ограничением <code>where</code> можно найти одну запись с помощью метода <code>first</code>. Следующий код найдёт запись, где slug равен <strong>first-post</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;first-post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если <a href="./../tailor/blueprints.html">тип записи</a> установлен как <code>single</code>, можно использовать метод <code>findSingleForSection</code> для поиска записи. Аналогично для поиска по UUID используется <code>findSingleForSectionUuid</code>. Эти методы гарантируют существование записи при поиске.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">findSingleForSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Homepage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">findSingleForSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;3328c303-7989-462e-b866-27e7037ba275&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="вставка-и-обновление-записеи"><a href="#вставка-и-обновление-записеи" class="header-anchor">#</a> Вставка и обновление записей</h3><p>Метод <code>inSection</code> может использоваться для динамического создания записей. Следующий код создаёт новую запись блога. Тот же код можно использовать для обновления существующей записи после её получения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Imported Post&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="глобальная-запись"><a href="#глобальная-запись" class="header-anchor">#</a> Глобальная запись</h2><p>Модель <code>Tailor\\Models\\GlobalRecord</code> используется для хранения контента глобальной записи.</p><h3 id="доступные-атрибуты-1"><a href="#доступные-атрибуты-1" class="header-anchor">#</a> Доступные атрибуты</h3><p>В дополнение к определённым полям формы, в полученной модели доступны следующие атрибуты.</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>Первичный ключ в базе данных.</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>UUID связанного чертежа.</td></tr></tbody></table></div><h3 id="получение-глобальнои-записи"><a href="#получение-глобальнои-записи" class="header-anchor">#</a> Получение глобальной записи</h3><p>Для поиска глобальной записи через PHP используйте модель <code>Tailor\\Models\\GlobalRecord</code> и вызовите статический метод <code>findForGlobal</code>, передав handle. Альтернативно можно выполнить поиск по UUID с помощью метода <code>findForGlobalUuid</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobalUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;7b193500-ac0b-481f-a79c-2a362646364d&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="работа-со-связанными-полями"><a href="#работа-со-связанными-полями" class="header-anchor">#</a> Работа со связанными полями</h2><p>Связанные поля могут включать <a href="./../../element/form/widget-repeater.html">поля-повторители</a> и <a href="./../../element/content/field-entries.html">поля записей</a>, и для чтения и записи этих полей требуются дополнительные шаги.</p><h3 id="жадная-загрузка-связеи"><a href="#жадная-загрузка-связеи" class="header-anchor">#</a> Жадная загрузка связей</h3><p>При чтении связанных полей вы можете жадно загрузить их в коллекцию с помощью метода <code>load</code>. Этот метод делает связанный контент доступным одним запросом, что оптимально для производительности.</p><p>Следующий пример жадно загружает поле <strong>categories</strong> и добавляет его к результату, а также демонстрирует передачу нескольких связанных полей.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="создание-связанных-полеи"><a href="#создание-связанных-полеи" class="header-anchor">#</a> Создание связанных полей</h3><p>При записи связанных полей можно вызвать имя связи как метод для получения определения связи, а затем вызвать метод <code>create()</code>, который возвращает вновь созданную связь.</p><p>Следующий пример находит первую публикацию блога в секции <strong>Blog\\Post</strong> и затем создаёт связанную категорию.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;price&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Используйте метод <code>make()</code> для создания нового пустого экземпляра модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$category</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если категория уже существует, используйте метод <code>add()</code>. Следующий пример добавляет первую категорию блога к первой публикации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$category</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Category&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$category</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Обратитесь к <a href="./../../extend/database/relations.html">статье о связях</a>, чтобы узнать больше о связях моделей.</p></div><h2 id="расширение-конструкторов-моделеи"><a href="#расширение-конструкторов-моделеи" class="header-anchor">#</a> Расширение конструкторов моделей</h2><p>Аналогично <a href="./../../extend/extending.html">расширению обычных моделей</a>, вы можете расширить конструктор модели <code>EntryRecord</code> с помощью метода <code>extendInSection</code> для нацеливания на конкретный чертёж. Метод <code>extendInSectionUuid</code> также может использоваться для более точного нацеливания.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">extendInSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.afterDelete&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been deleted!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Конструктор модели <code>GlobalRecord</code> также поддерживает расширение с помощью методов <code>extendInGlobal</code> и <code>extendInGlobalUuid</code> для нацеливания на конкретный чертёж.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">extendInGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been saved!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Методы <code>extendInSectionUuid</code> и <code>extendInGlobalUuid</code> не генерируют исключение, если чертёж не найден.</p></div><h2 id="расширение-моделеи-tailor"><a href="#расширение-моделеи-tailor" class="header-anchor">#</a> Расширение моделей Tailor</h2><p>В некоторых случаях вам может потребоваться объединить модели Tailor с <a href="./../../extend/system/models.html">обычными моделями базы данных</a>.</p><h3 id="связывание-tailor-с-обычными-моделями"><a href="#связывание-tailor-с-обычными-моделями" class="header-anchor">#</a> Связывание Tailor с обычными моделями</h3><p>Поле формы <code>recordfinder</code> вводит определение связи в обычную модель, например, модель, определённую плагином. <strong>modelClass</strong> должен ссылаться на класс модели, а свойство <strong>list</strong> обязательно для единичных связей, как указано в <strong>maxItems</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/test/models/product/columns.yaml
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>Подробнее о <a href="./../../element/form/widget-recordfinder.html">виджете формы recordfinder</a>.</p><h3 id="связывание-обычных-моделеи-с-tailor"><a href="#связывание-обычных-моделеи-с-tailor" class="header-anchor">#</a> Связывание обычных моделей с Tailor</h3><p>Поскольку все модели Tailor используют один и тот же класс модели, в определениях связей требуются дополнительные атрибуты. Трейт <code>Tailor\\Traits\\BlueprintRelationModel</code> реализует эти атрибуты для ссылки на модели Tailor, поддерживая связи Belongs To и Belongs To Many.</p><p>Когда трейт <code>BlueprintRelationModel</code> реализован в ваших моделях, вы можете указать свойство <code>blueprint</code> вместе с UUID чертежа, ссылающимся на чертёж Tailor. Следующий пример устанавливает связь Belongs To с классом <code>Tailor\\Models\\EntryRecord</code> под именем <strong>author</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>BlueprintRelationModel</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EntryRecord</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;blueprint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;6947ff28-b660-47d7-9240-24ca6d58aeae&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="создание-пользовательского-поля-контента"><a href="#создание-пользовательского-поля-контента" class="header-anchor">#</a> Создание пользовательского поля контента</h3><p>Вы также можете ссылаться на обычную модель, используя поле специфического типа. Например, пользовательское поле контента может быть жёстко привязано к модели <code>Customer</code>. Это включает создание пользовательского поля Tailor, которое предоставит полный доступ к модели и таблицам базы данных.</p><p>Внутри определения класса поля контента метод <code>extendModelObject</code> позволяет полю расширять модель записи, а <code>extendDatabaseTable</code> — добавлять столбец в таблицу базы данных.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">belongsTo</span><span class="token punctuation">[</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">MyOtherModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Это требует немного больше усилий, но результатом является простое определение <strong>type</strong> поля с минимальной конфигурацией.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Field
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mycontentfield
</code></pre></div><p>Подробнее о создании <a href="./../../extend/tailor-fields.html">пользовательских полей Tailor</a>.</p><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../element/form/widget-recordfinder.html">Виджет формы RecordFinder</a></li><li><a href="./../../extend/tailor-fields.html">Создание полей Tailor</a></li></ul></div>`,72))])}const v=o(i,[["render",d]]);export{m as __pageData,v as default};
